import {ActionList, ActionMenu} from '@primer/react'
import {useSearchParams} from '@github-ui/use-navigate'
import {useCallback, useEffect, useRef, useState} from 'react'
import styles from '../../styles/PeriodFilter.module.css'

const periods = [
  {label: 'Last 7 days', value: '7d'},
  {label: 'Last 14 days', value: '14d'},
  {label: 'Last 28 days', value: '28d'},
]

const PeriodFilter = () => {
  const [searchParams, setSearchParams] = useSearchParams()
  const currentPeriod = searchParams.get('period')
  const showButtonLabel = periods.find(p => p.value === currentPeriod)?.label ?? 'Last 28 days'
  const [open, setOpen] = useState(false)
  const listRef = useRef<HTMLUListElement>(null)

  const handleOpenChange = useCallback((nextOpen: boolean) => {
    setOpen(nextOpen)
  }, [])

  useEffect(() => {
    if (!open) return

    // Focus the first menu item after the overlay renders so NVDA users can navigate the menu
    const frameId = requestAnimationFrame(() => {
      const firstItem = listRef.current?.querySelector<HTMLElement>('[role="menuitemradio"]')
      firstItem?.focus()
    })

    return () => cancelAnimationFrame(frameId)
  }, [open])

  return (
    <ActionMenu open={open} onOpenChange={handleOpenChange}>
      <ActionMenu.Button aria-controls="timeframe-menu" block className={styles.buttonContent}>
        <span>Timeframe: {showButtonLabel}</span>
      </ActionMenu.Button>
      <ActionMenu.Overlay
        variant={{
          narrow: 'fullscreen',
        }}
      >
        <ActionList ref={listRef} id="timeframe-menu" aria-label="Period Filter" selectionVariant="single">
          {periods.map(period => (
            <ActionList.Item
              key={period.value}
              selected={period.value === currentPeriod}
              onSelect={() =>
                setSearchParams(
                  prev => {
                    const next = new URLSearchParams(prev)
                    next.set('period', period.value)
                    return next
                  },
                  {preventAutofocus: true},
                )
              }
            >
              {period.label}
            </ActionList.Item>
          ))}
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}

export default PeriodFilter
