import {InfoButton} from './InfoButton'

interface UsageInfoButtonProps {
  isEnterprise?: boolean
}

export function UsageInfoButton({isEnterprise = true}: UsageInfoButtonProps) {
  const entityText = isEnterprise ? 'enterprise' : 'organization'

  return (
    <InfoButton ariaLabel="Copilot usage dashboard info" title="How to use this dashboard">
      <InfoButton.Description role="definition" ariaLabel="Copilot usage purpose">
        Track adoption patterns and identify opportunities to increase Copilot usage across your {entityText}. These
        metrics only reflect IDE usage trends.
      </InfoButton.Description>
      <InfoButton.Description role="note" ariaLabel="Recommended approach">
        We recommend combining them with developer feedback and delivery data for a fuller view of impact.
      </InfoButton.Description>
      <InfoButton.Link
        href="https://resources.github.com/engineering-system-success-playbook/"
        ariaLabel="View GitHub Engineering System Success Playbook"
      >
        Check GitHub&apos;s Engineering System Success Playbook to get started.
      </InfoButton.Link>
      <InfoButton.Link
        href="https://docs.github.com/en/copilot/reference/copilot-usage-metrics"
        ariaLabel="Learn how Copilot metrics are calculated"
      >
        How are these metrics calculated?
      </InfoButton.Link>
      <InfoButton.Link
        href="https://docs.github.com/en/copilot/reference/interpret-copilot-metrics"
        ariaLabel="Learn how to interpret Copilot dashboard information"
      >
        How do I interpret the dashboard&apos;s information?
      </InfoButton.Link>
    </InfoButton>
  )
}
