import {InfoButton} from './InfoButton'

interface CodeGenerationInfoButtonProps {
  isEnterprise?: boolean
}

export function CodeGenerationInfoButton({isEnterprise = true}: CodeGenerationInfoButtonProps) {
  const entityText = isEnterprise ? 'enterprise' : 'organization'
  const docsBase = isEnterprise
    ? 'https://docs.github.com/en/enterprise-cloud@latest/copilot/reference/copilot-usage-metrics'
    : 'https://docs.github.com/en/copilot/reference/copilot-usage-metrics'

  return (
    <InfoButton ariaLabel="Copilot code generation dashboard info" title="How to use this dashboard">
      <InfoButton.Description role="definition" ariaLabel="Copilot Code Generation purpose">
        Track how code is being generated by users and agents across your {entityText}.
      </InfoButton.Description>
      <InfoButton.Description role="definition" ariaLabel="Data collection specification">
        These metrics only reflect IDE usage trends, showing how activity is distributed across models, languages, and
        modes, providing insight into how agent-driven development is being adopted within your organization.
      </InfoButton.Description>
      <InfoButton.Description role="note" ariaLabel="Recommended approach">
        We recommend combining them with developer feedback and delivery data for a fuller view of impact.
      </InfoButton.Description>
      <InfoButton.Link
        href="https://resources.github.com/engineering-system-success-playbook/"
        ariaLabel="View GitHub Engineering System Success Playbook"
      >
        Check GitHub&apos;s Engineering System Success Playbook to get started.
      </InfoButton.Link>
      <InfoButton.Link
        href={`${docsBase}/interpret-copilot-metrics`}
        ariaLabel="Learn how Copilot metrics are calculated"
      >
        How are these metrics calculated?
      </InfoButton.Link>
      <InfoButton.Link
        href={`${docsBase}/lines-of-code-metrics#new-lines-of-code-loc-feature`}
        ariaLabel="Learn how to interpret Copilot dashboard information"
      >
        Learn more about Lines of Code metrics
      </InfoButton.Link>
    </InfoButton>
  )
}
